=== FILE: sync_fifo.v ===
// sync_fifo.v : parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md and microarchitecture.md for sync_fifo.
//   - Occupancy is an explicit count register (works for any DEPTH >= 2).
//   - Pointers wrap from DEPTH-1 to 0 by compare, not by overflow.
//   - full/empty are compares on the count register.
//   - rd_data = mem[rd_ptr] (combinational read, 1-cycle write-to-read latency).
//   - rst_n is synchronous, active low; storage is datapath and is not reset.
`default_nettype none

module sync_fifo #(
  parameter integer DEPTH = 8,  // number of entries, 2 or more, any value
  parameter integer WIDTH = 8   // bits per entry, 1 or more
) (
  input  wire                       clk,
  input  wire                       rst_n,
  input  wire                       wr_en,
  input  wire [WIDTH-1:0]           wr_data,
  output wire                       full,
  input  wire                       rd_en,
  output wire [WIDTH-1:0]           rd_data,
  output wire                       empty,
  output wire [$clog2(DEPTH+1)-1:0] count
);

  localparam integer AW      = $clog2(DEPTH);
  localparam integer CW      = $clog2(DEPTH+1);
  localparam integer LAST_I  = DEPTH - 1;
  localparam integer DEPTH_I = DEPTH;
  localparam integer ONE_I   = 1;

  localparam [AW-1:0] LAST     = LAST_I[AW-1:0];
  localparam [AW-1:0] PTR_ONE  = ONE_I[AW-1:0];
  localparam [CW-1:0] CNT_ONE  = ONE_I[CW-1:0];
  localparam [CW-1:0] CNT_FULL = DEPTH_I[CW-1:0];

  // Storage (datapath, not reset)
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // State
  reg [AW-1:0] wr_ptr_q;
  reg [AW-1:0] rd_ptr_q;
  reg [CW-1:0] count_q;

  // Next state
  reg [AW-1:0] wr_ptr_d;
  reg [AW-1:0] rd_ptr_d;
  reg [CW-1:0] count_d;

  // Accepted requests: the flags gate the requests (overflow/underflow policy)
  wire wr_acc;
  wire rd_acc;

  assign full   = (count_q == CNT_FULL);
  assign empty  = (count_q == {CW{1'b0}});
  assign wr_acc = wr_en & ~full;
  assign rd_acc = rd_en & ~empty;

  assign count   = count_q;
  assign rd_data = mem[rd_ptr_q];

  // Write pointer next state
  always @* begin
    wr_ptr_d = wr_ptr_q;
    if (wr_acc) begin
      if (wr_ptr_q == LAST) wr_ptr_d = {AW{1'b0}};
      else                  wr_ptr_d = wr_ptr_q + PTR_ONE;
    end
  end

  // Read pointer next state
  always @* begin
    rd_ptr_d = rd_ptr_q;
    if (rd_acc) begin
      if (rd_ptr_q == LAST) rd_ptr_d = {AW{1'b0}};
      else                  rd_ptr_d = rd_ptr_q + PTR_ONE;
    end
  end

  // Count next state
  always @* begin
    case ({wr_acc, rd_acc})
      2'b10:   count_d = count_q + CNT_ONE;
      2'b01:   count_d = count_q - CNT_ONE;
      default: count_d = count_q;
    endcase
  end

  // State registers, synchronous active-low reset
  always @(posedge clk) begin
    if (!rst_n) begin
      wr_ptr_q <= {AW{1'b0}};
      rd_ptr_q <= {AW{1'b0}};
      count_q  <= {CW{1'b0}};
    end else begin
      wr_ptr_q <= wr_ptr_d;
      rd_ptr_q <= rd_ptr_d;
      count_q  <= count_d;
    end
  end

  // Storage write, only outside reset
  always @(posedge clk) begin
    if (rst_n && wr_acc) begin
      mem[wr_ptr_q] <= wr_data;
    end
  end

`ifdef FORMAL
  // Design-intent properties (not proven by this submission).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!rst_n);
  end

  // wr_ptr is count slots after rd_ptr, modulo DEPTH
  wire [31:0] f_sum    = {{(32-AW){1'b0}}, rd_ptr_q} + {{(32-CW){1'b0}}, count_q};
  wire [31:0] f_wr_exp = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;

  always @(*) begin
    if (f_past_valid) begin
      assert(count_q <= CNT_FULL);
      assert(full  == (count_q == CNT_FULL));
      assert(empty == (count_q == {CW{1'b0}}));
      assert(!(full && empty));
      assert(wr_ptr_q <= LAST);
      assert(rd_ptr_q <= LAST);
      assert(wr_ptr_q == f_wr_exp[AW-1:0]);
    end
  end

  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n)) begin
        assert(count_q  == {CW{1'b0}});
        assert(wr_ptr_q == {AW{1'b0}});
        assert(rd_ptr_q == {AW{1'b0}});
        assert(empty);
      end else begin
        case ({$past(wr_acc), $past(rd_acc)})
          2'b10:   assert(count_q == $past(count_q) + CNT_ONE);
          2'b01:   assert(count_q == $past(count_q) - CNT_ONE);
          default: assert(count_q == $past(count_q));
        endcase
        if ($past(wr_en) && $past(full))  assert(wr_ptr_q == $past(wr_ptr_q));
        if ($past(rd_en) && $past(empty)) assert(rd_ptr_q == $past(rd_ptr_q));
      end
    end
  end

  always @(posedge clk) begin
    if (f_past_valid && rst_n) begin
      cover(full);
      cover(wr_acc && rd_acc);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
