// sync_fifo_tb.v : self-checking testbench for sync_fifo.
// Two FIFOs (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) on the same stimulus,
// each checked every cycle against a reference queue, with coverage goals.
// Inputs change on the falling edge; outputs are checked on the falling edge
// (no sync_fifo output depends combinationally on an input).

module sync_fifo_tb_harness #(
  parameter integer DEPTH = 8,
  parameter integer WIDTH = 8,
  parameter integer DW    = 12
) (
  input  wire          clk,
  input  wire          rst_n,
  input  wire          wr_en,
  input  wire          rd_en,
  input  wire [DW-1:0] data_in,
  input  wire          done,
  output wire [31:0]   passed_o,
  output wire [31:0]   failed_o
);
  localparam integer CW = $clog2(DEPTH+1);
  localparam integer QW = WIDTH * DEPTH;

  wire [WIDTH-1:0] wr_data = data_in[WIDTH-1:0];
  wire             full;
  wire             empty;
  wire [WIDTH-1:0] rd_data;
  wire [CW-1:0]    count;

  sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) dut (
    .clk     (clk),
    .rst_n   (rst_n),
    .wr_en   (wr_en),
    .wr_data (wr_data),
    .full    (full),
    .rd_en   (rd_en),
    .rd_data (rd_data),
    .empty   (empty),
    .count   (count)
  );

  // Reference queue: entry 0 (bits WIDTH-1:0) is the oldest.
  // Bits above the m_cnt held entries are kept at zero.
  reg [QW-1:0] qv        = {QW{1'b0}};
  reg [QW-1:0] ext       = {QW{1'b0}};
  integer      m_cnt     = 0;
  reg          m_valid   = 1'b0;
  reg          acc_w     = 1'b0;
  reg          acc_r     = 1'b0;
  reg          seen_full = 1'b0;
  integer      w_tot     = 0;
  integer      r_tot     = 0;

  // Coverage counters
  integer cov_full       = 0;  // 1: filled to full
  integer cov_wr_full    = 0;  // 2: write while full
  integer cov_drain      = 0;  // 3: drained to empty after being full
  integer cov_rd_empty   = 0;  // 4: read while empty
  integer cov_both_empty = 0;  // 5: write and read together when empty
  integer cov_both_full  = 0;  // 6: write and read together when full
  integer cov_both_mid   = 0;  // 7: write and read together in between
  integer cov_wwrap      = 0;  // 8: write pointer wrap
  integer cov_rwrap      = 0;  // 9: read pointer wrap
  integer cov_rst        = 0;  // 10: reset during traffic (entries held)

  integer      passed    = 0;
  integer      failed    = 0;
  reg          cov_done  = 1'b0;
  reg          exp_full  = 1'b0;
  reg          exp_empty = 1'b1;
  reg [CW-1:0] exp_count = {CW{1'b0}};

  assign passed_o = passed;
  assign failed_o = failed;

  // Reference model, updated at the same edge as the DUT
  always @(posedge clk) begin
    if (!rst_n) begin
      if (m_valid && (m_cnt > 0)) cov_rst = cov_rst + 1;
      m_valid   = 1'b1;
      m_cnt     = 0;
      qv        = {QW{1'b0}};
      w_tot     = 0;
      r_tot     = 0;
      seen_full = 1'b0;
    end else if (m_valid) begin
      acc_w = wr_en && (m_cnt < DEPTH);
      acc_r = rd_en && (m_cnt > 0);

      if (m_cnt == DEPTH) begin
        cov_full  = cov_full + 1;
        seen_full = 1'b1;
      end
      if (wr_en && (m_cnt == DEPTH)) cov_wr_full  = cov_wr_full + 1;
      if (rd_en && (m_cnt == 0))     cov_rd_empty = cov_rd_empty + 1;
      if (wr_en && rd_en) begin
        if (m_cnt == 0)          cov_both_empty = cov_both_empty + 1;
        else if (m_cnt == DEPTH) cov_both_full  = cov_both_full + 1;
        else                     cov_both_mid   = cov_both_mid + 1;
      end
      if (acc_w && ((w_tot % DEPTH) == (DEPTH - 1))) cov_wwrap = cov_wwrap + 1;
      if (acc_r && ((r_tot % DEPTH) == (DEPTH - 1))) cov_rwrap = cov_rwrap + 1;

      if (acc_r) begin
        qv    = qv >> WIDTH;
        m_cnt = m_cnt - 1;
        r_tot = r_tot + 1;
      end
      if (acc_w) begin
        ext   = {{(QW-WIDTH){1'b0}}, wr_data};
        qv    = qv | (ext << (m_cnt * WIDTH));
        m_cnt = m_cnt + 1;
        w_tot = w_tot + 1;
      end
      if (acc_r && (m_cnt == 0) && seen_full) cov_drain = cov_drain + 1;
    end
  end

  task cov_goal(input integer hits, input integer id);
    begin
      if (hits > 0) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("sync_fifo DEPTH=%0d WIDTH=%0d: coverage goal %0d not reached",
               DEPTH, WIDTH, id);
      end
    end
  endtask

  // Output checks against the model, and final coverage checks
  always @(negedge clk) begin
    if (m_valid) begin
      exp_full  = (m_cnt == DEPTH);
      exp_empty = (m_cnt == 0);
      exp_count = m_cnt[CW-1:0];

      if (full !== exp_full) begin
        failed = failed + 1;
        $error("sync_fifo DEPTH=%0d t=%0t: full=%b, expected %b",
               DEPTH, $time, full, exp_full);
      end else begin
        passed = passed + 1;
      end

      if (empty !== exp_empty) begin
        failed = failed + 1;
        $error("sync_fifo DEPTH=%0d t=%0t: empty=%b, expected %b",
               DEPTH, $time, empty, exp_empty);
      end else begin
        passed = passed + 1;
      end

      if (count !== exp_count) begin
        failed = failed + 1;
        $error("sync_fifo DEPTH=%0d t=%0t: count=%0d, expected %0d",
               DEPTH, $time, count, exp_count);
      end else begin
        passed = passed + 1;
      end

      if (!exp_empty) begin
        if (rd_data !== qv[WIDTH-1:0]) begin
          failed = failed + 1;
          $error("sync_fifo DEPTH=%0d t=%0t: rd_data=%h, expected %h",
                 DEPTH, $time, rd_data, qv[WIDTH-1:0]);
        end else begin
          passed = passed + 1;
        end
      end
    end

    if (done && !cov_done) begin
      cov_done = 1'b1;
      cov_goal(cov_full,       1);
      cov_goal(cov_wr_full,    2);
      cov_goal(cov_drain,      3);
      cov_goal(cov_rd_empty,   4);
      cov_goal(cov_both_empty, 5);
      cov_goal(cov_both_full,  6);
      cov_goal(cov_both_mid,   7);
      cov_goal(cov_wwrap,      8);
      cov_goal(cov_rwrap,      9);
      cov_goal(cov_rst,        10);
    end
  end

endmodule

module sync_fifo_tb;
  reg         clk = 1'b0;
  reg         rst_n;
  reg         wr_en;
  reg         rd_en;
  reg  [11:0] wr_data;
  reg         done;

  wire [31:0] pass8;
  wire [31:0] fail8;
  wire [31:0] pass5;
  wire [31:0] fail5;
  reg  [31:0] total_pass;
  reg  [31:0] total_fail;

  reg  [8*64-1:0] nonce;
  integer         got_nonce;
  integer         rnd;
  integer         cyc;
  integer         k;
  reg  [1:0]      phase;
  reg  [6:0]      thw;
  reg  [6:0]      thr;
  reg             w;
  reg             r;

  always #5 clk = ~clk;

  sync_fifo_tb_harness #(.DEPTH(8), .WIDTH(8), .DW(12)) h8 (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
    .data_in(wr_data), .done(done), .passed_o(pass8), .failed_o(fail8)
  );

  sync_fifo_tb_harness #(.DEPTH(5), .WIDTH(12), .DW(12)) h5 (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
    .data_in(wr_data), .done(done), .passed_o(pass5), .failed_o(fail5)
  );

  // Apply one cycle of stimulus on the falling edge
  task drive(input rst_v, input w_v, input r_v);
    begin
      @(negedge clk);
      rst_n   = rst_v;
      wr_en   = w_v;
      rd_en   = r_v;
      rnd     = $random;
      wr_data = rnd[11:0];
    end
  endtask

  initial begin
    nonce     = {(8*64){1'b0}};
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (got_nonce == 0) $display("sync_fifo_tb: no nirmaan_nonce plusarg given");

    rst_n   = 1'b0;
    wr_en   = 1'b0;
    rd_en   = 1'b0;
    wr_data = 12'h000;
    done    = 1'b0;
    phase   = 2'd2;
    thw     = 7'd64;
    thr     = 7'd64;
    w       = 1'b0;
    r       = 1'b0;

    // Reset
    for (k = 0; k < 3; k = k + 1) drive(1'b0, 1'b0, 1'b0);

    // Read while empty
    drive(1'b1, 1'b0, 1'b1);
    // Write and read together when empty (only the write is accepted)
    drive(1'b1, 1'b1, 1'b1);
    // Write and read together in between
    drive(1'b1, 1'b1, 1'b1);
    // Fill to full, then write while full
    for (k = 0; k < 10; k = k + 1) drive(1'b1, 1'b1, 1'b0);
    // Write and read together when full (only the read is accepted)
    drive(1'b1, 1'b1, 1'b1);
    // Refill
    drive(1'b1, 1'b1, 1'b0);
    // Drain to empty, then read while empty
    for (k = 0; k < 12; k = k + 1) drive(1'b1, 1'b0, 1'b1);

    // Reset during traffic: hold some entries, then reset with requests active
    for (k = 0; k < 3; k = k + 1) drive(1'b1, 1'b1, 1'b0);
    drive(1'b0, 1'b1, 1'b1);
    drive(1'b0, 1'b1, 1'b1);
    for (k = 0; k < 3; k = k + 1) drive(1'b1, 1'b0, 1'b0);

    // Random traffic with stalls on both sides, in biased phases
    for (cyc = 0; cyc < 4000; cyc = cyc + 1) begin
      if ((cyc % 40) == 0) begin
        rnd   = $random;
        phase = rnd[1:0];
        case (phase)
          2'd0:    begin thw = 7'd115; thr = 7'd30;  end
          2'd1:    begin thw = 7'd30;  thr = 7'd115; end
          2'd2:    begin thw = 7'd64;  thr = 7'd64;  end
          default: begin thw = 7'd110; thr = 7'd110; end
        endcase
      end
      rnd = $random;
      w   = (rnd[6:0]  < thw);
      r   = (rnd[13:7] < thr);
      if ((cyc == 1500) || (cyc == 1501) || (cyc == 2700)) drive(1'b0, w, r);
      else                                                  drive(1'b1, w, r);
    end

    // Finish: request coverage checks, then report the verdict
    drive(1'b1, 1'b0, 1'b0);
    done = 1'b1;
    for (k = 0; k < 4; k = k + 1) @(negedge clk);

    total_pass = pass8 + pass5;
    total_fail = fail8 + fail5;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_pass, total_fail);
    $finish;
  end

endmodule
=== END FILE ===
